// 1. Detect if the original trigger message was a voice note
const triggerMessages = $('WhatsApp Trigger').item.json.messages;
const isVoice = triggerMessages?.[0]?.type === 'audio';

// 2. Link + emoji cleaning function (only used when isVoice === true)
function cleanText(text) {
  if (typeof text !== 'string') return text;
  let result = text
    .replace(/\p{Extended_Pictographic}/gu, '')
    .replace(/[\u{1F1E6}-\u{1F1FF}]/gu, '')
    .replace(/\u200D/g, '')
    .replace(/\uFE0F/g, '');

  if (isVoice) {
    result = result
      .replace(/\[([^\]]+)\]\((?:https?:\/\/|www\.)[^\s)]+\)/gi, '$1')
      .replace(/\(?\bhttps?:\/\/[^\s)]+\)?/gi, '')
      .replace(/\(?\bwww\.[^\s)]+\)?/gi, '')
      .replace(/\(?\b[a-z0-9-]+(?:\.[a-z0-9-]+)+\/[^\s)]*\)?/gi, '');
  }

  return result
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

// 3. Apply to the AI's response text field
// ⚠️ Replace 'output' below with the ACTUAL field name holding the AI reply
if ($input.item.json && typeof $input.item.json.output === 'string') {
  $input.item.json.output = cleanText($input.item.json.output);
}

return $input.item;

// هذا الكود يغيّر فقط اسم الملف والـ mimeType الظاهر للـ binary
// ملاحظة مهمة: هذا لا يحوّل الترميز الفعلي (codec) للصوت
// لازم يتنفذ بعد خطوة تحويل حقيقية (ffmpeg عبر Execute Command أو API تحويل)
// وإلا واتساب مش هيقدر يشغّل الملف كرسالة صوتية

for (const item of $input.all()) {
  if (item.binary && item.binary.data) {
    // تحديث اسم الملف والامتداد
    item.binary.data.fileName = 'voice_message.ogg';
    item.binary.data.fileExtension = 'ogg';
    // الـ mimeType الصح المطلوب لرسائل الصوت في واتساب
    item.binary.data.mimeType = 'audio/ogg; codecs=opus';
  }
}

return $input.all();

const token = $('Text Processing').item.json.MY_TOKEN;
const webhookUrl = 'YOUR_APPS_SCRIPT_WEBHOOK_URL';

const callMoodle = (wsfunction, params = {}) => helpers.httpRequest({
  method: 'GET',
  url: 'https://moodle.najah.edu/webservice/rest/server.php',
  qs: { wstoken: token, wsfunction, moodlewsrestformat: 'json', ...params },
  json: true,
  timeout: 15000,
});

const keyOf = u => String(u).split('&token=')[0].split('?token=')[0];

const [existingData, coursesRes] = await Promise.all([
  helpers.httpRequest({ method: 'GET', url: webhookUrl, json: true, timeout: 15000 })
    .catch(() => ({ items: [], lastId: 0 })),
  callMoodle('core_enrol_get_users_courses', { userid: 25688 }).catch(() => []),
]);

// رقم كل ملف موجود في الشيت
const idByKey = new Map((existingData.items || []).map(([u, id]) => [keyOf(u), id]));
let currentId = existingData.lastId || 0;
const courses = Array.isArray(coursesRes) ? coursesRes : [];

const allContents = await Promise.all(
  courses.map(c =>
    callMoodle('core_course_get_contents', { courseid: c.id })
      .then(r => [c, Array.isArray(r) ? r : []])
      .catch(() => [c, []])
  )
);

const files = [];
for (const [course, sections] of allContents) {
  for (const sec of sections) {
    for (const m of (sec.modules || [])) {
      if (m.modname === 'forum' || m.modname === 'url') continue;
      for (const f of (m.contents || [])) {
        if (f.type === 'file' && f.filename?.toLowerCase().endsWith('.pdf')) {
          files.push({
            name: f.filename,
            course: course.fullname,
            ts: f.timemodified || 0,
            fileurl: f.fileurl,
          });
        }
      }
    }
  }
}
files.sort((a, b) => b.ts - a.ts);

const currentTime = new Date().toISOString().replace('T', ' ').slice(0, 19);
const newRows = [];
const list = [];

for (const f of files) {
  let id = idByKey.get(keyOf(f.fileurl));
  if (id === undefined) {
    id = ++currentId;
    newRows.push([f.name, f.course, '', `${f.fileurl}&token=${token}`, id, currentTime]);
  }
  list.push({ id, course: f.course, name: f.name });
}

if (newRows.length > 0) {
  await helpers.httpRequest({
    method: 'POST', url: webhookUrl, body: { values: newRows }, json: true, timeout: 15000,
  }).catch(() => {});
}

// فلتر اختياري باسم المادة أو الملف
const q = String(typeof query === 'string' ? query : '').trim().toLowerCase();
const filtered = q
  ? list.filter(x => x.course.toLowerCase().includes(q) || x.name.toLowerCase().includes(q))
  : list;

const grouped = {};
for (const x of filtered.slice(0, 60)) {
  (grouped[x.course] = grouped[x.course] || []).push({ id: x.id, name: x.name });
}

return JSON.stringify(
  Object.entries(grouped).map(([course, files]) => ({ course, files }))
);

const { id: ID, pass: PASS } = $('Text Processing').first().json;
const BASE = "https://zajeles.najah.edu";
const store = $getWorkflowStaticData("global");
if (!ID || !PASS) return `missing creds: id=${!!ID} pass=${!!PASS}`;
// ---- كوكيز ----
store.jar = store.jar || {};
const jar = store.jar;

const saveCookies = (res) => {
  const h = res.headers || {};
  for (const line of [].concat(h["set-cookie"] || [])) {
    const pair = line.split(";")[0];
    const i = pair.indexOf("=");
    if (i > 0) jar[pair.slice(0, i).trim()] = pair.slice(i + 1).trim();
  }
};
const cookieHeader = () =>
  Object.entries(jar).map(([k, v]) => `${k}=${v}`).join("; ");

const request = async (path, method = "GET", body) => {
  const res = await helpers.httpRequest({
    url: BASE + path,
    method,
    headers: {
      Cookie: cookieHeader(),
      "User-Agent": "Mozilla/5.0",
      Referer: BASE + "/servlet/start",
      ...(body !== undefined
        ? { "Content-Type": "application/x-www-form-urlencoded" }
        : {}),
    },
    body,
    encoding: "arraybuffer",
    json: false,
    returnFullResponse: true,
    ignoreHttpStatusCode: true,
    timeout: 15000,
  });
  saveCookies(res);
  return new TextDecoder("windows-1256").decode(Buffer.from(res.body));
};

// ---- تحليل الجدول ----
const clean = (s) =>
  s.replace(/<[^>]*>/g, " ").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&")
   .replace(/\s+/g, " ").trim();

const parse = (html) => {
  const courses = [];
  const rowRe = /<tr[^>]*>([\s\S]*?)<\/tr>/gi;
  let r;
  while ((r = rowRe.exec(html))) {
    const cells = [];
    const cellRe = /<t[hd][^>]*>([\s\S]*?)<\/t[hd]>/gi;
    let c;
    while ((c = cellRe.exec(r[1]))) cells.push(clean(c[1]));

    if (cells.length >= 15 && /^\d{8}$/.test(cells[0])) {
      const credits = Number(cells[4]);
      const total = Number(cells[12]);
      const excused = Number(cells[13]);
      courses.push({
        name: "اسم المساق : " + cells[3],
        section: "رقم الشعبة : " + (cells[1] ? (cells[1].split("/")[1] || "") : ""),
        credits: "وزن المساق : " + cells[4],
        absenceHours: "مجموع ساعات الغياب : " + cells[12],
        unexcused: "ساعات الغياب بدون عذر : " + (total - excused),
        excused: "ساعات الغياب بعذر : " + cells[13],
        rest: "ساعات الغياب المسموح بها المتبقية : " + (credits * 4 - total),
      });
    }
  }
  return courses;
};

const getCourses = async () =>
  parse(await request("/servlet/program", "POST", "cou=68"));

const login = async () => {
  for (const k of Object.keys(jar)) delete jar[k];
  await request("/servlet/ZajelGate", "POST", `startDate=&liun=${ID}`);
  await request("/servlet/ZajelGt", "POST", `gsw=${encodeURIComponent(PASS)}`);
  await request("/servlet/login", "POST", `startDate=${Date.now()}`);
  await request("/servlet/mainN");
  await request("/servlet/start");
};

// ---- 1) جرّب الكوكيز المخزّنة ----
let courses = Object.keys(jar).length ? await getCourses() : [];

// ---- 2) انتهت الجلسة؟ سجّل دخولك من جديد ----
if (!courses.length) {
  await login();
  courses = await getCourses();
}

if (!courses.length) {
  return "login_failed: could not fetch attendance data.";
}

return courses.map(j =>
  `${j.name} , ${j.section} , ${j.credits}\n` +
  `${j.absenceHours} , ${j.rest}\n` +
  `${j.unexcused} , ${j.excused}`
).join("\n-----------------------------------\n");

const webhookUrl = 'YOUR_APPS_SCRIPT_WEBHOOK_URL';

// تحويل الأرقام العربية إلى لاتينية
const normalize = s => String(s ?? '').replace(/[\u0660-\u0669]/g, d => String(d.charCodeAt(0) - 0x0660));

// استخراج الأرقام بدون تكرار + ترتيب تصاعدي
const ids = [...new Set(
  (normalize(typeof query === 'string' ? query : JSON.stringify(query)).match(/\d+/g) || [])
    .map(Number)
    .filter(n => n > 0)
)].sort((a, b) => a - b).slice(0, 15);

if (!ids.length) return '';

const res = await helpers.httpRequest({
  method: 'GET',
  url: webhookUrl,
  qs: { ids: ids.join(',') },
  json: true,
  timeout: 15000,
}).catch(() => null);

if (!res || !res.files) return '';

// الروابط فقط، مرتبة حسب الرقم، كل رابط في سطر
return res.files
  .sort((a, b) => a.id - b.id)
  .map(f => f.url)
  .filter(Boolean)
  .join('\n');

