const BASE = 'http://host.docker.internal:8000';

// تطبيع: إزالة التشكيل والإيموجي وتوحيد الحروف
const norm = s => String(s ?? '')
  .replace(/[\u064B-\u0652\u0640]/g, '')
  .replace(/[أإآ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه')
  .replace(/[^\p{L}\p{N}\s>]/gu, ' ')
  .replace(/\s+/g, ' ').toLowerCase().trim();

const raw = await helpers.httpRequest({
  method: 'GET', url: BASE + '/paths', json: true, timeout: 15000,
}).catch(() => null);

if (!raw) return 'ERROR: paths request failed';

// يدعم مصفوفة نصوص أو كائناً مفاتيحه هي المسارات
const list = Array.isArray(raw) ? raw : (raw.paths || []);
const paths = list
  .map(p => (typeof p === 'string' ? p : p?.path))
  .filter(Boolean);

const parts = String(typeof query === 'string' ? query : '')
  .split('|').map(norm).filter(Boolean);

const match = (list, ps) => list.filter(p => ps.every(x => norm(p).includes(x)));

let res = match(paths, parts);
if (!res.length && parts.length > 1) res = match(paths, [parts[0]]); // جرّب المادة فقط

if (!res.length) return 'NOT_FOUND';
return JSON.stringify(res.slice(0, 15));

const BASE = 'http://host.docker.internal:8000';

const full = String(typeof query === 'string' ? query : '').trim();
if (!full) return 'ERROR: empty path';

// آخر جزء من المسار بإيموجيه كما هو
const label = full.split('>').pop().trim();

const res = await helpers.httpRequest({
  method: 'POST',
  url: BASE + '/run',
  body: { path: [label] },   // مصفوفة بعنصر واحد
  json: true,
  timeout: 60000,
}).catch(e => ({ __error: String(e.message || e).slice(0, 300) }));

if (res === null || res === undefined) return 'ERROR: empty response';
if (res.__error) return 'ERROR: ' + res.__error;
return typeof res === 'string' ? res : JSON.stringify(res);
